function x({registerIndicator:b,sourceValues:d,nulls:f}){b({id:"oa-bbw",name:"Bollinger Band Width (BBW)",category:"Volatility",placement:"pane",inputs:[{key:"period",type:"number",label:"Period",default:20,min:1,max:5e3,step:1},{key:"source",type:"source",label:"Source",default:"close"},{key:"multiplier",type:"number",label:"StdDev Multiplier",default:2,min:.001,max:100,step:.1}],plots:[{key:"bbw",type:"line",title:"BBW",style:{color:"#ffeb3b",lineWidth:2}}],calc(s,o){const y=Math.max(1,Math.floor(Number(o.period)||20)),h=Math.max(.001,Number(o.multiplier)||2),u=d(s,o.source||"close"),l=s.length,i=Math.max(1,y),t=new Array(l);for(let e=0;e<l;e++)t[e]=Number.isFinite(u[e])?u[e]:0;const m=new Array(l).fill(NaN);let a=0,n=0;for(let e=0;e<l;e++){if(e>=i){const c=t[e-i];a-=c,n-=c*c}a+=t[e],n+=t[e]*t[e];const r=Math.min(e+1,i);if(r<=1)continue;const p=a/r,M=h*Math.sqrt(Math.max(0,n/r-p*p));m[e]=2*M}return{bbw:f(m)}}})}export{x as default};
